theorem compiler_checked {P : Prog C Γ Γ'} {F : Evm.Frag Γ} {b L frame : Nat}
    (compiled : Evm.Compiler.Compilation b F P) {base : Nat → Fin Evm.W}
    {σ : State C Γ} {mc : Evm.Machine}
