constructors.clause_source:
| allIntro {Γ : Ctx} {H : Hyps C Γ₀ Γ} {x : Var} {p : PrimTy} {φ : Fml C (.val p :: Γ)}
    (h : Proves C R Γ₀ (H.all x p) φ) : Proves C R Γ₀ H (.all x p φ)
/-- An update in front of the formula joins the context. -/

| updIntro {Γ Δ : Ctx} {H : Hyps C Γ₀ Γ} {m : Modality} {U : Upd C Γ Δ} {φ : Fml C Δ}
    (h : Proves C R Γ₀ (H.upd m U) φ) : Proves C R Γ₀ H (.upd m U φ)
/-- The hidden binder joins the context (Lean only). -/

| updates {Γ Δ Γ' Γ₁ Γ₂ : Ctx} {H : Hyps C Γ₀ Γ} {m : Modality} {s : Stmt C Γ Γ'}
    {ω : Prog C Γ' Γ₁} {κ : Frames C Γ₁ Γ₂} {φ : Fml C Γ₂}
    {U : Upd C Γ Δ} {V : Upd C Δ Γ'}
    (d : s.step (H.fresh (.modal m (.cons s ω) κ φ)) m = .updates U V)
    (h : Proves C R Γ₀ ((H.upd m U).upd m V) (.modalK m ω κ φ))
    (hR : R.admits m s = true := by rule_admits) :
    Proves C R Γ₀ H (.modal m (.cons s ω) κ φ)
/-- `sp.push() /= se`: the zero-divisor branch encloses both updates. -/

| guardedUpdates {Γ Δ Γ₁ Γ₂ : Ctx} {H : Hyps C Γ₀ Γ} {m : Modality}
    {s : Stmt C Γ Γ} {ω : Prog C Γ Γ₁} {κ : Frames C Γ₁ Γ₂} {φ : Fml C Γ₂}
    {c : Fml C Γ} {U : Upd C Γ Δ} {V : Upd C Δ Γ}
    (d : s.step (H.fresh (.modal m (.cons s ω) κ φ)) m = .guardedUpdates c U V)
    (thn : Proves C R Γ₀ (H.pre c) (.upd m U (.upd m V (.modalK m ω κ φ))))
    (els : Proves C R Γ₀ (H.pre (.not c)) (.modal m (.cons .revert ω) κ φ))
    (hR : R.admits m s = true := by rule_admits) :
    Proves C R Γ₀ H (.modal m (.cons s ω) κ φ)
/-- A taclet that produces statements: they replace the first one, their
fresh locals popped after them (`pop .capture`). -/

| bind {Γ Γ' Γ₁ Γ₂ : Ctx} {H : Hyps C Γ₀ Γ} {m : Modality} {s : Stmt C Γ Γ'}
    {ω : Prog C Γ' Γ₁} {κ : Frames C Γ₁ Γ₂} {φ : Fml C Γ₂} {x : Var} {t : LTy}
    {P : Prog C (t :: Γ) Γ'}
    (d : s.step (H.fresh (.modal m (.cons s ω) κ φ)) m = .bind x t P)
    (h : Proves C R Γ₀ (H.bind m x t) (.modal m P (.seq ω κ) φ))
    (hR : R.admits m s = true := by rule_admits) :
    Proves C R Γ₀ H (.modal m (.cons s ω) κ φ)
/-- A taclet that branches: two goals, KeY's, each branch a block ended
as the premise says (`}` for an `if`). -/

| split {Γ Γ₁ Γ₂ Δ₁ Δ₂ : Ctx} {H : Hyps C Γ₀ Γ} {m : Modality} {s : Stmt C Γ Γ}
    {ω : Prog C Γ Γ₁} {κ : Frames C Γ₁ Γ₂} {φ : Fml C Γ₂} {b : BlockKind} {c c' : Fml C Γ}
    {P : Prog C Γ Δ₁} {Q : Prog C Γ Δ₂}
    (d : s.step (H.fresh (.modal m (.cons s ω) κ φ)) m = .split b c c' P Q)
    (thn : Proves C R Γ₀ (H.pre c) (.modalK m P (.pop b P.ext (.seq ω κ)) φ))
    (els : Proves C R Γ₀ (H.pre c') (.modalK m Q (.pop b Q.ext (.seq ω κ)) φ))
    (hR : R.admits m s = true := by rule_admits) :
    Proves C R Γ₀ H (.modal m (.cons s ω) κ φ)
/-- A taclet that checks (`assertSimple`): the goal with the condition
assumed ("Holds"), and the condition ("Violated"). -/

| empty {Γ Γ₂ : Ctx} {H : Hyps C Γ₀ Γ} {m : Modality} {κ : Frames C Γ Γ₂} {φ : Fml C Γ₂}
    (h : Proves C R Γ₀ H (κ.exit m φ)) : Proves C R Γ₀ H (.modal m .nil κ φ)
/-- `closeTrue`, behind a context with no diamond update. -/

| merge {Γ Δ Ε : Ctx} {H : Hyps C Γ₀ Γ} {m : Modality} {bs : List (Modality × Var × LTy)}
    {U : Upd C Γ Δ} {U' : Upd C (Binds.ctx bs Γ) (Binds.ctx bs Δ)}
    {V : Upd C (Binds.ctx bs Δ) Ε} {W : Upd C (Binds.ctx bs Γ) Ε} {φ : Fml C Ε}
    (hU : U.liftBinds? bs = some U') (hW : U'.seqPar V = some W)
    (h : Proves C R Γ₀ ((H.binds bs).upd m W) φ) :
    Proves C R Γ₀ (((H.upd m U).binds bs).upd m V) φ
/-- A term taclet `t ⇝ t'` in the right-hand sides of the last update, under
the box, where `t'` returns wherever `t` does, the same value
(`Tm.EvalRefines`; a Theory law onto a literal): today's `updRw`, its
closed occurrences read at the empty scope (`Upd.rwC`). -/

| updIntro {Γ Δ : Ctx} {H : Hyps C Γ₀ Γ} {m : Modality} {U : Upd C Γ Δ} {φ : Fml C Δ}
    (h : ProvesC I pay Γ₀ (H.upd m U) φ) : ProvesC I pay Γ₀ H (.upd m U φ)
/-- The hidden binder joins the context (Lean only). -/

| updates {Γ Δ Γ' Γ₁ Γ₂ : Ctx} {H : Hyps C Γ₀ Γ} {m : Modality} {s : Stmt C Γ Γ'}
    {ω : Prog C Γ' Γ₁} {κ : Frames C Γ₁ Γ₂} {φ : Fml C Γ₂}
    {U : Upd C Γ Δ} {V : Upd C Δ Γ'}
    (d : Rule C (H.freshC I (.modal m (.cons s ω) κ φ)) m s (.updates U V))
    (hs : s.forksIn pay = false)
    (h : ProvesC I pay Γ₀ ((H.upd m U).upd m V) (.modalK m ω κ φ)) :
    ProvesC I pay Γ₀ H (.modal m (.cons s ω) κ φ)
/-- The outer zero-divisor branch of `sp.push() /= se`, with callbacks
permitted only in the continuation. -/

| guardedUpdates {Γ Δ Γ₁ Γ₂ : Ctx} {H : Hyps C Γ₀ Γ} {m : Modality}
    {s : Stmt C Γ Γ} {ω : Prog C Γ Γ₁} {κ : Frames C Γ₁ Γ₂} {φ : Fml C Γ₂}
    {c : Fml C Γ} {U : Upd C Γ Δ} {V : Upd C Δ Γ}
    (d : Rule C (H.freshC I (.modal m (.cons s ω) κ φ)) m s (.guardedUpdates c U V))
    (hs : s.forksIn pay = false)
    (thn : ProvesC I pay Γ₀ (H.pre c) (.upd m U (.upd m V (.modalK m ω κ φ))))
    (els : ProvesC I pay Γ₀ (H.pre (.not c)) (.modal m (.cons .revert ω) κ φ)) :
    ProvesC I pay Γ₀ H (.modal m (.cons s ω) κ φ)
/-- A rule that produces statements, on a statement that runs no other and
pays nothing, when they pay nothing either. -/

| unfoldReceiver {Γ Γv ps Γf Γ₁ Γ₂ : Ctx} {H : Hyps C Γ₀ Γ} {m : Modality}
    {E : Ty} {f : Name} {args : Args C Γ ps} {r : Var}
    {body : Prog C ([.alias (.array E)] ++ ps) Γf}
    {code : Prog C Γ Γv} {value : Src C Γv E} {k : Nat}
    {ω : Prog C Γ Γ₁} {κ : Frames C Γ₁ Γ₂} {φ : Fml C Γ₂}
    (d : Rule C (H.freshC I (.modal m
      (.cons (.callReceiverPush f args r body code value) ω) κ φ)) m
      (.callReceiverPush f args r body code value)
      (.unfold (callReceiverPushCapture k f args r body code value) (.push (.push .refl))))
    (h : ProvesC I pay Γ₀ H (.modal m (callReceiverPushCapture k f args r body code value)
      (.pop .capture (.push (.push .refl)) (.seq ω κ)) φ)) :
    ProvesC I pay Γ₀ H (.modal m (.cons (.callReceiverPush f args r body code value) ω) κ φ)
/-- A declaration with its initializer dropped (`localValueDeclInitDrop`),
when the assignment pays nothing. -/

| bind {Γ Γ' Γ₁ Γ₂ : Ctx} {H : Hyps C Γ₀ Γ} {m : Modality} {s : Stmt C Γ Γ'}
    {ω : Prog C Γ' Γ₁} {κ : Frames C Γ₁ Γ₂} {φ : Fml C Γ₂} {x : Var} {t : LTy}
    {P : Prog C (t :: Γ) Γ'}
    (d : Rule C (H.freshC I (.modal m (.cons s ω) κ φ)) m s (.bind x t P))
    (hs : s.forksIn pay = false)
    (hP : P.callsBack pay = false)
    (h : ProvesC I pay Γ₀ (H.bind m x t) (.modal m P (.seq ω κ) φ)) :
    ProvesC I pay Γ₀ H (.modal m (.cons s ω) κ φ)
/-- A rule that branches (`ifElseSplit`, `requireSimple`): KeY's two goals,
each branch a block ended as the premise says, whatever its branches pay. -/

| split {Γ Γ₁ Γ₂ Δ₁ Δ₂ : Ctx} {H : Hyps C Γ₀ Γ} {m : Modality} {s : Stmt C Γ Γ}
    {ω : Prog C Γ Γ₁} {κ : Frames C Γ₁ Γ₂} {φ : Fml C Γ₂} {b : BlockKind} {c c' : Fml C Γ}
    {P : Prog C Γ Δ₁} {Q : Prog C Γ Δ₂}
    (d : Rule C (H.freshC I (.modal m (.cons s ω) κ φ)) m s (.split b c c' P Q))
    (thn : ProvesC I pay Γ₀ (H.pre c) (.modalK m P (.pop b P.ext (.seq ω κ)) φ))
    (els : ProvesC I pay Γ₀ (H.pre c') (.modalK m Q (.pop b Q.ext (.seq ω κ)) φ)) :
    ProvesC I pay Γ₀ H (.modal m (.cons s ω) κ φ)
/-- `emptyModality`. -/

| callNone {Γ ps Γf Γ₁ Γ₂ : Ctx} {H : Hyps C Γ₀ Γ} {m : Modality} {f : Name}
    {args : Args C Γ ps} {body : Prog C ([] ++ ps) Γf} {ω : Prog C Γ Γ₁} {κ : Frames C Γ₁ Γ₂}
    {φ : Fml C Γ₂}
    (h : ProvesC I pay Γ₀ H (.modal m
      (args.declsThen (.cons (.block (body.wk (Thin.atop ps Γ)).2.2) .nil))
      (.pop .capture (Ext.append Γ ps) (.seq ω κ)) φ)) :
    ProvesC I pay Γ₀ H (.modal m (.cons (.call f args .none body) ω) κ φ)
/-- `functionBodyExpand` of a call with targets whose body may call back:
the parameters declared, the return variables at their defaults, the body
as a block, the parameters thinned out from under the return variables. -/

| callVal {Γ ps Γf Γ₁ Γ₂ : Ctx} {H : Hyps C Γ₀ Γ} {m : Modality} {f : Name}
    {args : Args C Γ ps} {p : PrimTy} {r : Var} {res : Option (Idx Γ (.val p))}
    {body : Prog C ([.val p] ++ ps) Γf} {ω : Prog C Γ Γ₁} {κ : Frames C Γ₁ Γ₂} {φ : Fml C Γ₂}
    (h : ProvesC I pay Γ₀ H (.modal m (args.declsThen (.cons (.declLocal p r none)
        (.cons (.block (body.wk (Thin.atop (.val p :: ps) Γ)).2.2) (Prog.callResult res))))
      (.pop .capture (.push (Ext.append Γ ps)) (.seq ω κ)) φ)) :
    ProvesC I pay Γ₀ H (.modal m (.cons (.call f args (.val p r res) body) ω) κ φ)
/-- `internalCallExpand` of a call of a storage reference whose body may
call back: the return alias unset, the body as a block, the parameters
thinned out from under the alias. -/

| callStorage {Γ ps Γf Γ₁ Γ₂ : Ctx} {H : Hyps C Γ₀ Γ} {m : Modality} {f : Name}
    {args : Args C Γ ps} {R : RefTy} {r : Var} {body : Prog C ([.alias R] ++ ps) Γf}
    {ω : Prog C (.alias R :: Γ) Γ₁} {κ : Frames C Γ₁ Γ₂} {φ : Fml C Γ₂}
    (h : ProvesC I pay Γ₀ H (.modal m (args.declsThen (.cons (.declStorage R r none)
        (.cons (.block (body.wk (Thin.atop (.alias R :: ps) Γ)).2.2) .nil)))
      (.drop (.keep (Thin.ofExt (Ext.append Γ ps))) (.seq ω κ)) φ)) :
    ProvesC I pay Γ₀ H (.modal m (.cons (.call f args (.storage R r) body) ω) κ φ)
/-- `internalCallExpand` of a call of a memory reference whose body may
call back: the return object allocated at its default, the body as a
block, the parameters thinned out from under the object. -/

| callMem {Γ ps Γf Γ₁ Γ₂ : Ctx} {H : Hyps C Γ₀ Γ} {m : Modality} {f : Name}
    {args : Args C Γ ps} {R : RefTy} {r : Var} {hd : (Ty.ref R).defaultOkS = true}
    {hm : (Ty.ref R).mapFree = true} {body : Prog C ([.mem R] ++ ps) Γf}
    {ω : Prog C (.mem R :: Γ) Γ₁} {κ : Frames C Γ₁ Γ₂} {φ : Fml C Γ₂}
    (h : ProvesC I pay Γ₀ H (.modal m (args.declsThen (.cons (.declMem R r none hd hm)
        (.cons (.block (body.wk (Thin.atop (.mem R :: ps) Γ)).2.2) .nil)))
      (.drop (.keep (Thin.ofExt (Ext.append Γ ps))) (.seq ω κ)) φ)) :
    ProvesC I pay Γ₀ H (.modal m (.cons (.call f args (.mem R r hd hm) body) ω) κ φ)
/-- **`transferWithCallbackBox`**: the invariant after the booking ("invariant
on exit", `{U} I`), and the rest resumed after the callback, from any state
the callee may leave in which the invariant holds (`{U} {havoc} (I → [ ω ] φ)`). -/

| callReceiver {Γ ps Γf : Ctx} {E : Ty} {σ : State C Γ} {f : Name}
    {args : Args C Γ ps} {r : Var} {body : Prog C ([.alias (.array E)] ++ ps) Γf}
    {op : ReceiverOp C Γ E} {o : COut C σ.H (.alias (.array E) :: Γ)} :
    ExecS J σ (.call f args (.storage _ r) body) o →
      ExecS J σ (.callReceiver f args r body op) (o.receiverOp op)
/-- A successful getter precedes every callback in the deferred operand. -/

| callReceiverPush {Γ ps Γf Γv : Ctx} {E : Ty} {σ : State C Γ} {f : Name}
    {args : Args C Γ ps} {r : Var} {body : Prog C ([.alias (.array E)] ++ ps) Γf}
    {code : Prog C Γ Γv} {value : Src C Γv E}
    {a : Out C σ.H (.alias (.array E) :: Γ)} {ref : SRef C (.array E)}
    {u : COut C a.st.H Γv} :
    ExecS J σ (.call f args (.storage _ r) body) (.ok a) →
    a.st.env.1 = some ref → ExecP J (a.st.drop (.push .refl)) code u →
    ExecS J σ (.callReceiverPush f args r body code value)
      ((u.pushPrefix code.ext value ref).map (fun b => ⟨b.st, a.ext.trans b.ext⟩))
/-- An unset getter result reverts before the operand's first effect. -/

| callReceiverPushUnset {Γ ps Γf Γv : Ctx} {E : Ty} {σ : State C Γ} {f : Name}
    {args : Args C Γ ps} {r : Var} {body : Prog C ([.alias (.array E)] ++ ps) Γf}
    {code : Prog C Γ Γv} {value : Src C Γv E}
    {a : Out C σ.H (.alias (.array E) :: Γ)} :
    ExecS J σ (.call f args (.storage _ r) body) (.ok a) → a.st.env.1 = none →
    ExecS J σ (.callReceiverPush f args r body code value) (.halt .revert)
/-- Getter failure stops `f().push(e)` before its operand. -/

| callReceiverPushHalt {Γ ps Γf Γv : Ctx} {E : Ty} {σ : State C Γ} {f : Name}
    {args : Args C Γ ps} {r : Var} {body : Prog C ([.alias (.array E)] ++ ps) Γf}
    {code : Prog C Γ Γv} {value : Src C Γv E} {err : THalt} :
    ExecS J σ (.call f args (.storage _ r) body) (.halt err) →
    ExecS J σ (.callReceiverPush f args r body code value) (.halt err)
/-- A getter's invariant violation stops `f().push(e)` before its operand. -/

| tryRevert {Γ ρ κ Γ₁ Γ₂ Γ₃ Γ₄ : Ctx} {σ : State C Γ} {call : ExtCall C Γ} {rets : Binders ρ}
    {ok : Prog C (ρ ++ Γ) Γ₁} {err : Prog C Γ Γ₂} {code : CodeBinder κ}
    {pnc : Prog C (κ ++ Γ) Γ₃} {other : Prog C Γ Γ₄}
    {ps Γf : Ctx} {sargs : Args C Γ ps} {sbody : Prog C (ρ ++ ps) Γf} {self : Bool} :
    ExecS J σ (.tryCall call rets ok err code pnc other sargs sbody self) (.halt .revert)
/-- Data that the return variables do not decode. -/

| tryDecode {Γ ρ κ Γ₁ Γ₂ Γ₃ Γ₄ : Ctx} {σ : State C Γ} {call : ExtCall C Γ} {rets : Binders ρ}
    {ok : Prog C (ρ ++ Γ) Γ₁} {err : Prog C Γ Γ₂} {code : CodeBinder κ}
    {pnc : Prog C (κ ++ Γ) Γ₃} {other : Prog C Γ Γ₄}
    {ps Γf : Ctx} {sargs : Args C Γ ps} {sbody : Prog C (ρ ++ ps) Γf} {self : Bool} {vs : List Word} {e : THalt} :
    rets.decodeT (C := C) (H := σ.H) vs = .error e →
      ExecS J σ (.tryCall call rets ok err code pnc other sargs sbody self) (.halt e)
/-- KeY's "invariant on exit": control leaves with `J` broken. -/

| tryViolated {Γ ρ κ Γ₁ Γ₂ Γ₃ Γ₄ : Ctx} {σ : State C Γ} {call : ExtCall C Γ} {rets : Binders ρ}
    {ok : Prog C (ρ ++ Γ) Γ₁} {err : Prog C Γ Γ₂} {code : CodeBinder κ}
    {pnc : Prog C (κ ++ Γ) Γ₃} {other : Prog C Γ Γ₄}
    {ps Γf : Ctx} {sargs : Args C Γ ps} {sbody : Prog C (ρ ++ ps) Γf} {self : Bool} :
    ¬ J.at σ → ExecS J σ (.tryCall call rets ok err code pnc other sargs sbody self) .violated
/-- KeY's "call succeeded": `J` kept, any state the callee may leave in
which `J` holds, the return data bound, the clause run, its locals popped.
A self-call reaches the oracle only at another contract's address (the
last premise, `TRun.tryCall`'s order). -/

| tryError {Γ ρ κ Γ₁ Γ₂ Γ₃ Γ₄ : Ctx} {σ : State C Γ} {call : ExtCall C Γ} {rets : Binders ρ}
    {ok : Prog C (ρ ++ Γ) Γ₁} {err : Prog C Γ Γ₂} {code : CodeBinder κ}
    {pnc : Prog C (κ ++ Γ) Γ₃} {other : Prog C Γ Γ₄}
    {ps Γf : Ctx} {sargs : Args C Γ ps} {sbody : Prog C (ρ ++ ps) Γf} {self : Bool} {o : COut C σ.H Γ₂} :
    (self = true → (call.addr.evalT σ).1 ≠ σ.tx.selfAddress.1) → ExecP J σ err o →
      ExecS J σ (.tryCall call rets ok err code pnc other sargs sbody self) (o.map (Out.drop err.ext))
/-- "Panic caught", with the code bound. -/

| tryPanic {Γ ρ κ Γ₁ Γ₂ Γ₃ Γ₄ : Ctx} {σ : State C Γ} {call : ExtCall C Γ} {rets : Binders ρ}
    {ok : Prog C (ρ ++ Γ) Γ₁} {err : Prog C Γ Γ₂} {code : CodeBinder κ}
    {pnc : Prog C (κ ++ Γ) Γ₃} {other : Prog C Γ Γ₄}
    {ps Γf : Ctx} {sargs : Args C Γ ps} {sbody : Prog C (ρ ++ ps) Γf} {self : Bool} {v : Word} {o : COut C σ.H Γ₃} :
    (self = true → (call.addr.evalT σ).1 ≠ σ.tx.selfAddress.1) →
    ExecP J (σ.withEnv (TEnv.append κ (code.decodeT v) σ.env)) pnc o →
      ExecS J σ (.tryCall call rets ok err code pnc other sargs sbody self)
        (o.map (Out.drop ((Ext.append Γ κ).trans pnc.ext)))
/-- "Other failure caught". -/

| tryOther {Γ ρ κ Γ₁ Γ₂ Γ₃ Γ₄ : Ctx} {σ : State C Γ} {call : ExtCall C Γ} {rets : Binders ρ}
    {ok : Prog C (ρ ++ Γ) Γ₁} {err : Prog C Γ Γ₂} {code : CodeBinder κ}
    {pnc : Prog C (κ ++ Γ) Γ₃} {other : Prog C Γ Γ₄}
    {ps Γf : Ctx} {sargs : Args C Γ ps} {sbody : Prog C (ρ ++ ps) Γf} {self : Bool} {o : COut C σ.H Γ₄} :
    (self = true → (call.addr.evalT σ).1 ≠ σ.tx.selfAddress.1) → ExecP J σ other o →
      ExecS J σ (.tryCall call rets ok err code pnc other sargs sbody self) (o.map (Out.drop other.ext))
/-- A self-call (`Stmt.tryCall`'s `self`, `docs/options.md` O8): the
receiver is the contract, whose function runs as an inlined call, and the
success clause from the state it leaves, its locals popped. -/

| trySelfOk {Γ ρ κ Γ₁ Γ₂ Γ₃ Γ₄ : Ctx} {σ : State C Γ} {call : ExtCall C Γ} {rets : Binders ρ}
    {ok : Prog C (ρ ++ Γ) Γ₁} {err : Prog C Γ Γ₂} {code : CodeBinder κ}
    {pnc : Prog C (κ ++ Γ) Γ₃} {other : Prog C Γ Γ₄}
    {ps Γf : Ctx} {sargs : Args C Γ ps} {sbody : Prog C (ρ ++ ps) Γf}
    {o₁ : Out C σ.H (ρ ++ Γ)} {o : COut C o₁.st.H Γ₁} :
    (call.addr.evalT σ).1 ≠ 0 → (call.addr.evalT σ).1 = σ.tx.selfAddress.1 →
    ExecS J σ (.call call.fn sargs (.rets rets.toRet) sbody) (.ok o₁) → ExecP J o₁.st ok o →
      ExecS J σ (.tryCall call rets ok err code pnc other sargs sbody true)
        (o.map fun o' => ⟨o'.st.drop ((Ext.append Γ ρ).trans ok.ext), o₁.ext.trans o'.ext⟩)
/-- A self-call whose callee exhausts or diverges: the caller does too. -/

| trySelfError {Γ ρ κ Γ₁ Γ₂ Γ₃ Γ₄ : Ctx} {σ : State C Γ} {call : ExtCall C Γ} {rets : Binders ρ}
    {ok : Prog C (ρ ++ Γ) Γ₁} {err : Prog C Γ Γ₂} {code : CodeBinder κ}
    {pnc : Prog C (κ ++ Γ) Γ₃} {other : Prog C Γ Γ₄}
    {ps Γf : Ctx} {sargs : Args C Γ ps} {sbody : Prog C (ρ ++ ps) Γf} {o : COut C σ.H Γ₂}
    {d : List UInt8} :
    (call.addr.evalT σ).1 ≠ 0 → (call.addr.evalT σ).1 = σ.tx.selfAddress.1 →
    ExecS J σ (.call call.fn sargs (.rets rets.toRet) sbody) (.halt (.revertWith d)) → ExecP J σ err o →
      ExecS J σ (.tryCall call rets ok err code pnc other sargs sbody true)
        (o.map (Out.drop err.ext))
/-- A self-call whose callee reverts: the catch-all, from the caller's
state. -/

| trySelfOther {Γ ρ κ Γ₁ Γ₂ Γ₃ Γ₄ : Ctx} {σ : State C Γ} {call : ExtCall C Γ} {rets : Binders ρ}
    {ok : Prog C (ρ ++ Γ) Γ₁} {err : Prog C Γ Γ₂} {code : CodeBinder κ}
    {pnc : Prog C (κ ++ Γ) Γ₃} {other : Prog C Γ Γ₄}
    {ps Γf : Ctx} {sargs : Args C Γ ps} {sbody : Prog C (ρ ++ ps) Γf} {o : COut C σ.H Γ₄}
    {e : THalt} :
    (call.addr.evalT σ).1 ≠ 0 → (call.addr.evalT σ).1 = σ.tx.selfAddress.1 →
    ExecS J σ (.call call.fn sargs (.rets rets.toRet) sbody) (.halt e) →
    (e = .revert ∨ ∃ d, e = .revertWith d) → ExecP J σ other o →
      ExecS J σ (.tryCall call rets ok err code pnc other sargs sbody true)
        (o.map (Out.drop other.ext))
/-- A self-call whose callee panics: the `Panic` clause, with the code its
data carries (`TRun.tryCall`), any code where it panics by a halt of its own
(the transaction's, `TRun.selfPanicCode`). -/

| trySelfPanic {Γ ρ κ Γ₁ Γ₂ Γ₃ Γ₄ : Ctx} {σ : State C Γ} {call : ExtCall C Γ} {rets : Binders ρ}
    {ok : Prog C (ρ ++ Γ) Γ₁} {err : Prog C Γ Γ₂} {code : CodeBinder κ}
    {pnc : Prog C (κ ++ Γ) Γ₃} {other : Prog C Γ Γ₄}
    {ps Γf : Ctx} {sargs : Args C Γ ps} {sbody : Prog C (ρ ++ ps) Γf} {v : Word}
    {o : COut C σ.H Γ₃} {e : THalt} :
    (call.addr.evalT σ).1 ≠ 0 → (call.addr.evalT σ).1 = σ.tx.selfAddress.1 →
    ExecS J σ (.call call.fn sargs (.rets rets.toRet) sbody) (.halt e) →
    (e = .panic ∨ ∃ d, e = .revertWith d ∧ Semantics.decodePanic d = some v) →
    ExecP J (σ.withEnv (TEnv.append κ (code.decodeT v) σ.env)) pnc o →
      ExecS J σ (.tryCall call rets ok err code pnc other sargs sbody true)
        (o.map (Out.drop ((Ext.append Γ κ).trans pnc.ext)))
/-- A self-call whose callee leaves the contract with `J` broken. -/

| trySelfViolated {Γ ρ κ Γ₁ Γ₂ Γ₃ Γ₄ : Ctx} {σ : State C Γ} {call : ExtCall C Γ}
    {rets : Binders ρ} {ok : Prog C (ρ ++ Γ) Γ₁} {err : Prog C Γ Γ₂} {code : CodeBinder κ}
    {pnc : Prog C (κ ++ Γ) Γ₃} {other : Prog C Γ Γ₄}
    {ps Γf : Ctx} {sargs : Args C Γ ps} {sbody : Prog C (ρ ++ ps) Γf} :
    (call.addr.evalT σ).1 ≠ 0 → (call.addr.evalT σ).1 = σ.tx.selfAddress.1 →
    ExecS J σ (.call call.fn sargs (.rets rets.toRet) sbody) .violated →
      ExecS J σ (.tryCall call rets ok err code pnc other sargs sbody true) .violated
/-- A loop that pays, whose condition halts. -/

| catchDataHalt {Γ ρ ps Γf Γ₁ : Ctx} {σ : State C Γ} {call : ExtCall C Γ} {rets : Binders ρ}
    {sargs : Args C Γ ps} {sbody : Prog C (ρ ++ ps) Γf} {self : Bool} {kind : CatchKind}
    {x : Var} {body : Prog C (.mem bytesR :: Γ) Γ₁} {e : THalt} :
    (Prog.callsBack J.pay sbody || Prog.callsBack J.pay body) = true → e ≠ .panic →
      ExecS J σ (.catchData call rets sargs sbody self kind x body) (.halt e)

  | catchDataBody {Γ ρ ps Γf Γ₁ : Ctx} {σ : State C Γ} {call : ExtCall C Γ} {rets : Binders ρ}
      {sargs : Args C Γ ps} {sbody : Prog C (ρ ++ ps) Γf} {self : Bool} {kind : CatchKind}
      {x : Var} {body : Prog C (.mem bytesR :: Γ) Γ₁} {bs : List UInt8}
      {o₁ : Out C σ.H (.mem bytesR :: Γ)} {o : COut C o₁.st.H Γ₁} :
      (Prog.callsBack J.pay sbody || Prog.callsBack J.pay body) = true →
      TRun.litBytesT bs TRun.nil σ = .ok o₁ → ExecP J o₁.st body o →
        ExecS J σ (.catchData call rets sargs sbody self kind x body)
          (o.map fun o' => ⟨o'.st.drop ((Ext.push .refl).trans body.ext), o₁.ext.trans o'.ext⟩)

/-- `ExecP J σ P o`: the same, for a sequence. -/

| cons {Γ Γ₁ Γ₂ : Ctx} {σ : State C Γ} {s : Stmt C Γ Γ₁} {P : Prog C Γ₁ Γ₂}
    {o₁ : Out C σ.H Γ₁} {o : COut C o₁.st.H Γ₂} :
    ExecS J σ s (.ok o₁) → ExecP J o₁.st P o → ExecP J σ (.cons s P) (o.map (Out.cat o₁))

| seq {Γ Γ₁ : Ctx} {σ : State C Γ} {ω : Prog C Γ Γ₁} {κ : Frames C Γ₁ Γ₀} {o₁ : Out C σ.H Γ₁}
    {o : COut C o₁.st.H Γ₀} :
    ExecP J σ ω (.ok o₁) → ExecF J o₁.st κ o → ExecF J σ (.seq ω κ) (o.map (Out.cat o₁))

| pop {Γ Γ' : Ctx} {σ : State C Γ'} {b : BlockKind} {h : Ext Γ Γ'} {κ : Frames C Γ Γ₀}
    {o : COut C σ.H Γ₀} :
    ExecF J (σ.drop h) κ o → ExecF J σ (.pop b h κ) o
